});

test('addLine defaults discountPercent to 0 when not provided', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3 });
