});

test('createInvoice accepts decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 12.5 }],
  });
